await p.evaluate(()=>document.querySelectorAll('details').forEach(d=>d.open=true));
const m=await p.evaluate(()=>{const wide=[...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().right>document.documentElement.clientWidth+1).map(e=>e.tagName+'.'+e.className).slice(0,5);
 return {sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,bsw:document.body.scrollWidth,items:document.querySelectorAll('.item').length,ins:document.querySelectorAll('ins').length,del:document.querySelectorAll('del').length,details:document.querySelectorAll('details.old').length,h:document.documentElement.scrollHeight,wide}});
console.log(scheme,JSON.stringify(m),'errors:',errs);
if(scheme==='light'){await p.screenshot({path:'/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/adj-check.png',clip:{x:0,y:0,width:400,height:1800},fullPage:true});}
await p.close();}
await b.close()})();
EOF
